float pixelSize = 10.0;
vec2 center = vec2(0.5);
float radius = 0.5;

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 normalPixel = pixelSize/iResolution.xy;

    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    vec2 pixelUV = normalPixel * floor(uv/normalPixel);

    vec2 cellUV = fract(uv / normalPixel);

    float dist = length(cellUV - radius);
    float relativeRadius = radius * max(uv.x, radius);

    vec3 col = texture(iChannel0, pixelUV).rgb;
    float lum = dot(vec3(0.2126, 0.7152, 0.0722), col);

    col = vec3(1.0 - step(lum, 0.5));
    float lumRadius = radius * lum;
    float circle = smoothstep(lumRadius - 0.01, lumRadius + 0.01, dist);

    col = mix(col, vec3(0.0), circle);

    // Output to screen
    fragColor.rgb = col;
}
